-- A command's output: here just the host name.
local host = vim.trim(dbdash.system("hostname").stdout)

-- Data computed in Lua; dbdash.query() could read it from a database instead.
local rows = {}
for i = args.days - 1, 0, -1 do
  local t = os.time() - i * 86400
  rows[#rows + 1] = { os.date("%m-%d", t), 50 + math.floor(30 * math.sin(i / 2)), host }
end
return { columns = { "day", "load", "host" }, rows = rows }
